-- Preview ONLY: verify jarvis-preview ID, absent vo_* tables and account Free limits before execution.
-- No legacy table/data/backup changes. No IF NOT EXISTS masking schema mismatches.
CREATE TABLE vo_agents(id TEXT PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL, enabled INTEGER NOT NULL, budget_limit INTEGER NOT NULL CHECK(budget_limit>=0), version INTEGER NOT NULL, body_json TEXT NOT NULL);
CREATE TABLE vo_tasks(id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES vo_agents(id), status TEXT NOT NULL, version INTEGER NOT NULL, last_command TEXT NOT NULL, objective TEXT NOT NULL, input_json TEXT NOT NULL, output_json TEXT NOT NULL, body_json TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE vo_approvals(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES vo_tasks(id),action TEXT NOT NULL,status TEXT NOT NULL,task_version INTEGER NOT NULL,reviewer TEXT,body_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE vo_runs(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES vo_tasks(id),agent_id TEXT NOT NULL REFERENCES vo_agents(id),status TEXT NOT NULL,operation_id TEXT,model TEXT,estimated_cost INTEGER NOT NULL DEFAULT 0,body_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE vo_metrics(id TEXT PRIMARY KEY,task_id TEXT REFERENCES vo_tasks(id),metric TEXT NOT NULL,value INTEGER NOT NULL CHECK(value>0),source TEXT NOT NULL,body_json TEXT NOT NULL,observed_at INTEGER NOT NULL);
CREATE INDEX idx_vo_tasks_status ON vo_tasks(status,updated_at);
CREATE INDEX idx_vo_approvals_task ON vo_approvals(task_id,created_at);
CREATE INDEX idx_vo_runs_agent ON vo_runs(agent_id,created_at);
CREATE INDEX idx_vo_metrics_task ON vo_metrics(task_id,observed_at);

-- Singleton revision/CAS plus recovery snapshot; mirrors above contain the five domain models.
CREATE TABLE vo_workspace(id TEXT PRIMARY KEY CHECK(id='office'),version INTEGER NOT NULL,last_command TEXT NOT NULL,body_json TEXT NOT NULL);
